package org.firstinspires.ftc.teamcode.tuning;

import com.qualcomm.hardware.gobilda.GoBildaPinpointDriver;
import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;
import com.qualcomm.robotcore.eventloop.opmode.TeleOp;
import com.qualcomm.robotcore.hardware.CRServo;
import com.qualcomm.robotcore.hardware.DcMotorEx;
import com.qualcomm.robotcore.hardware.Servo;
import com.qualcomm.robotcore.hardware.VoltageSensor;

import org.firstinspires.ftc.teamcode.config.DeviceNames;

import java.util.Locale;

// Generated by refract-suite ftc-construct. PRACTICE ONLY. Setup program 1 (prerequisites D-1).
// Moves nothing. Checks every device name, the battery, that each motor's encoder counts (and no other one)
// when only that part is turned by hand, and that both Pinpoint pods count. Afterwards it stays as a live
// readout of everything.
@TeleOp(name = "1 Check Devices", group = "19859 Setup")
public class DeviceReadout extends LinearOpMode {
    private static final String[] MOTORS = {DeviceNames.LEFT_FRONT, DeviceNames.LEFT_BACK, DeviceNames.RIGHT_FRONT,
            DeviceNames.RIGHT_BACK, DeviceNames.INTAKE, DeviceNames.POLLEN_FEED, DeviceNames.FRONT_FLYWHEEL, DeviceNames.BACK_FLYWHEEL};
    private static final String[] MOTOR_PARTS = {"left-front wheel", "left-back wheel", "right-front wheel",
            "right-back wheel", "intake roller", "POLLEN feeder wheels", "front flywheel", "back flywheel"};
    private static final String[] SERVOS = {DeviceNames.FRONT_GATE, DeviceNames.BACK_GATE, DeviceNames.BACK_GATE_2,
            DeviceNames.FRONT_YAW, DeviceNames.BACK_YAW};
    // the ramp servos are continuous rotation: configured as "Continuous Rotation Servo", not "Servo"
    private static final String[] CR_SERVOS = {DeviceNames.RAMP_LEFT, DeviceNames.RAMP_RIGHT};
    // check thresholds, not robot measurements
    private static final int ENCODER_MOVED_TICKS = 30;
    private static final int POD_MOVED_TICKS = 1000;
    private static final double BATTERY_OK_V = 12.5;
    private static final int STEPS = 4;

    @Override
    public void runOpMode() {
        Guide g = new Guide(telemetry, 1);
        DcMotorEx[] motors = new DcMotorEx[MOTORS.length];
        StringBuilder missing = new StringBuilder();
        int found = 0;
        for (int i = 0; i < MOTORS.length; i++) {
            try {
                motors[i] = hardwareMap.get(DcMotorEx.class, MOTORS[i]);
                found++;
            } catch (IllegalArgumentException e) {
                missing.append(MOTORS[i]).append(' ');
            }
        }
        Servo[] servos = new Servo[SERVOS.length];
        for (int i = 0; i < SERVOS.length; i++) {
            try {
                servos[i] = hardwareMap.get(Servo.class, SERVOS[i]);
                found++;
            } catch (IllegalArgumentException e) {
                missing.append(SERVOS[i]).append(' ');
            }
        }
        for (String name : CR_SERVOS) {
            try {
                hardwareMap.get(CRServo.class, name);
                found++;
            } catch (IllegalArgumentException e) {
                missing.append(name).append(" (as Continuous Rotation Servo) ");
            }
        }
        GoBildaPinpointDriver pinpoint = null;
        try {
            pinpoint = hardwareMap.get(GoBildaPinpointDriver.class, DeviceNames.PINPOINT);
            found++;
        } catch (IllegalArgumentException e) {
            missing.append(DeviceNames.PINPOINT);
        }
        int total = MOTORS.length + SERVOS.length + CR_SERVOS.length + 1;

        while (opModeInInit()) {
            g.header(0, 0, "Before you start");
            g.why("A wrong name or a loose encoder cable makes every later program fail in confusing ways. This finds them first.");
            g.doThis("Put the robot on a box so the wheels spin freely. Battery plugged in.");
            g.say("This program moves nothing. You will turn parts by hand.");
            g.doThis("Press START.");
            g.update();
        }
        if (isStopRequested()) return;

        int step = 1, part = 0;
        int[] startTicks = new int[MOTORS.length];
        boolean[] moved = new boolean[MOTORS.length];
        StringBuilder notCounting = new StringBuilder(), crossed = new StringBuilder();
        int podStartX = 0, podStartY = 0;
        boolean podX = false, podY = false, ticksTaken = false, podsTaken = false, recorded = false;
        String note = "";

        while (opModeIsActive()) {
            boolean next = gamepad1.crossWasPressed(), back = gamepad1.triangleWasPressed();
            // in step 3 triangle means "turn this part again"
            if (back && step > 1 && step != 3 && step <= STEPS) step--;
            double volts = battery();
            if (pinpoint != null) pinpoint.update();

            switch (step) {
                case 1:
                    g.header(1, STEPS, "Device names");
                    g.why("Every name in the code must match the Robot Controller configuration exactly.");
                    g.goal("\"Every device name matches.\"");
                    g.value("Found", found + " of " + total);
                    if (missing.length() == 0) {
                        g.good("Every device name matches.");
                        g.keys("cross = next");
                        if (next) step++;
                    } else {
                        g.warn("Missing: " + missing.toString().trim());
                        g.doThis("On the Driver Station: Configure Robot, fix these names exactly (see setup step D-1), save, then run this program again.");
                    }
                    break;
                case 2:
                    g.header(2, STEPS, "Battery");
                    g.why("Tuning on a weak battery gives wrong numbers.");
                    g.goal("12.5 V or more.");
                    g.value("Battery", String.format(Locale.US, "%.2f V", volts));
                    if (volts >= BATTERY_OK_V) g.good("Charged enough.");
                    else g.warn("Below 12.5 V: swap in a charged battery for tuning.");
                    g.keys("cross = next, triangle = back");
                    if (next) step++;
                    break;
                case 3:
                    // one part at a time: its own encoder must count and no other one, so a cable in another motor's port shows
                    if (!ticksTaken || back) {
                        for (int i = 0; i < MOTORS.length; i++) {
                            if (motors[i] != null) startTicks[i] = motors[i].getCurrentPosition();
                            moved[i] = false;
                        }
                        ticksTaken = true;
                    }
                    StringBuilder others = new StringBuilder(), pairs = new StringBuilder();
                    for (int i = 0; i < MOTORS.length; i++) {
                        if (motors[i] != null && Math.abs(motors[i].getCurrentPosition() - startTicks[i]) > ENCODER_MOVED_TICKS) moved[i] = true;
                        if (moved[i] && i != part) {
                            others.append(others.length() == 0 ? "" : ", ").append(MOTORS[i]);
                            pairs.append(MOTORS[part]).append('-').append(MOTORS[i]).append(' ');
                        }
                    }
                    String mixed = others.toString();
                    g.header(3, STEPS, "Encoders: " + MOTOR_PARTS[part] + " (" + (part + 1) + " of " + MOTORS.length + ")");
                    g.why("Speed, aim and odometry need every encoder to count, each in its own motor's port.");
                    g.goal("OK: only this part's encoder counts.");
                    g.doThis("Turn ONLY the " + MOTOR_PARTS[part] + " now, a bit, by hand. Touch nothing else.");
                    g.value(MOTORS[part] + " encoder", (motors[part].getCurrentPosition() - startTicks[part]) + " ticks");
                    if (!mixed.isEmpty()) {
                        g.warn("MIXED UP: " + MOTORS[part] + " and " + mixed + ". Turning the " + MOTOR_PARTS[part] + " counted on " + mixed + ".");
                        g.say("Two parts turned at once, or one still spinning? Let everything stop, press triangle, turn ONLY the "
                                + MOTOR_PARTS[part] + " again.");
                        g.say("Same again? An encoder cable is in the wrong port: each one goes in the same port number as its own motor.");
                    } else if (moved[part]) {
                        g.good("OK: its encoder counts, and no other one did.");
                    } else {
                        g.say("Waiting for it to count. Never counts = its encoder cable is loose or in the wrong port (same port number as its motor).");
                    }
                    boolean ok = moved[part] && mixed.isEmpty();
                    g.keys(ok ? "cross = next, triangle = turn it again" : "cross = skip (noted for the programmer), triangle = turn it again");
                    if (next) {
                        if (!moved[part]) notCounting.append(MOTORS[part]).append(' ');
                        crossed.append(pairs);
                        part++;
                        ticksTaken = false;
                        if (part == MOTORS.length) {
                            note = g.record("encodersNotCounting", notCounting.length() == 0 ? "none" : notCounting.toString().trim());
                            String error = g.record("encodersCrossed", crossed.length() == 0 ? "none" : crossed.toString().trim());
                            if (note.isEmpty()) note = error;
                            part = 0;
                            notCounting.setLength(0);
                            crossed.setLength(0);
                            step++;
                        }
                    }
                    break;
                case 4:
                    g.header(4, STEPS, "Pinpoint odometry pods");
                    g.why("The two pod wheels are how the robot knows where it is.");
                    g.goal("Both pods say OK.");
                    if (pinpoint == null) {
                        g.warn("No Pinpoint found: fix the name (step 1).");
                        break;
                    }
                    if (!podsTaken) {
                        podStartX = pinpoint.getEncoderX();
                        podStartY = pinpoint.getEncoderY();
                        podsTaken = true;
                    }
                    if (Math.abs(pinpoint.getEncoderX() - podStartX) > POD_MOVED_TICKS) podX = true;
                    if (Math.abs(pinpoint.getEncoderY() - podStartY) > POD_MOVED_TICKS) podY = true;
                    g.value("Pinpoint", String.valueOf(pinpoint.getDeviceStatus()));
                    g.doThis("Put the robot on the floor. Push it straight forward about a foot, then slide it sideways about a foot.");
                    if (podX) g.good("OK   forward pod counts");
                    else g.say("...  forward pod (push forward)");
                    if (podY) g.good("OK   strafe pod counts");
                    else g.say("...  strafe pod (slide sideways)");
                    g.keys(podX && podY ? "cross = finish, triangle = back" : "both pods must count first, triangle = back");
                    if (next && podX && podY) step++;
                    break;
                default:
                    if (!recorded) {
                        note = g.record("devicesFound", found + "/" + total);
                        g.record("batteryVolts", volts);
                        recorded = true;
                        g.loadNextOnStop(this);
                    }
                    g.header(0, 0, "Done");
                    g.finished("");
                    g.say("Live readout below (for checking later):");
                    for (int i = 0; i < MOTORS.length; i++) {
                        if (motors[i] != null) g.value(MOTORS[i], String.format(Locale.US, "%d ticks, %.0f ticks/s", motors[i].getCurrentPosition(), motors[i].getVelocity()));
                    }
                    for (int i = 0; i < SERVOS.length; i++) {
                        if (servos[i] != null) g.value(SERVOS[i], String.format(Locale.US, "last command %.3f", servos[i].getPosition()));
                    }
                    if (pinpoint != null) g.value("Pinpoint pods x / y", pinpoint.getEncoderX() + " / " + pinpoint.getEncoderY());
                    g.value("Battery", String.format(Locale.US, "%.2f V", volts));
                    break;
            }
            if (!note.isEmpty()) g.warn(note);
            g.update();
        }
    }

    private double battery() {
        double volts = 0;
        for (VoltageSensor s : hardwareMap.voltageSensor) volts = Math.max(volts, s.getVoltage());
        return volts;
    }
}
